function validate([n, pick]) {
  if (!Number.isInteger(n) || n < 2 || n > 10) return 'n is between 2 and 10.';
  if (pick.length < 1 || pick.length > 100) return 'pick needs 1 to 100 entries.';
  for (const entry of pick) {
    if (!Array.isArray(entry) || entry.length !== 2) return 'Each pick is a pair [player, color].';
    const [x, y] = entry;
    if (!Number.isInteger(x) || x < 0 || x > n - 1) return 'Each player is between 0 and n - 1.';
    if (!Number.isInteger(y) || y < 0 || y > 10) return 'Each color is between 0 and 10.';
  }
  return null;
}

