function winningPlayerCount(n, pick) {
  const count = Array.from({ length: n }, () => new Array(11).fill(0));
  const won = new Array(n).fill(false);
  for (const [player, color] of pick) {
    count[player][color]++;
    if (count[player][color] > player) {
      won[player] = true;
    }
  }
  let winners = 0;
  for (let player = 0; player < n; player++) {
    if (won[player]) {
      winners++;
    }
  }
  return winners;
}

