function winningPlayerCount(n, pick) {
  let total = 0;
  for (let i = 0; i < n; i++) {
    let wins = false;
    for (let c = 0; c <= 10; c++) {
      const taken = pick.filter(([x, y]) => x === i && y === c).length;
      if (taken >= i + 1) wins = true;
    }
    if (wins) total++;
  }
  return total;
