function generate(rand, size) {
  const n = size === 'large' ? 10 : 2 + Math.floor(rand() * 4);
  const length = size === 'large' ? 100 : 1 + Math.floor(rand() * 12);
  // A narrow palette makes repeated colors (and so winners) likely.
  const colors = 1 + Math.floor(rand() * (size === 'large' ? 11 : 4));
  const offset = Math.floor(rand() * (12 - colors));
  const pick = Array.from({ length }, () => [Math.floor(rand() * n), offset + Math.floor(rand() * colors)]);
  return [n, pick];
}
